<script setup lang="ts">
import AcademicNav from '@/Components/AcademicNav.vue'; import OwnershipBadge from '@/Components/OwnershipBadge.vue'; import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import { Head, Link, router, usePage } from '@inertiajs/vue3'; import { reactive } from 'vue';
const props=defineProps<{courses:any[];subjects:any[];gradeLevels:any[];filters:any}>(); const canManage=usePage<any>().props.auth.permissions.includes('courses.manage'); const filters=reactive({...props.filters}); const apply=()=>router.get(route('academic.courses.index'),filters,{preserveState:true,replace:true});
</script>
<template><Head title="Courses"/><AuthenticatedLayout><div class="d-flex justify-content-between mb-3"><div><h1 class="h2">Courses</h1><p class="text-secondary">Grade-aware instructional offerings grouped by subject.</p></div><Link v-if="canManage" class="btn btn-primary align-self-start" :href="route('academic.courses.create')">Add course</Link></div><AcademicNav/>
<form class="card card-body mb-3" @submit.prevent="apply"><div class="row g-2 align-items-end"><div class="col-md-5"><label for="course-subject-filter" class="form-label">Subject</label><select id="course-subject-filter" v-model="filters.subject_id" class="form-select"><option :value="null">All subjects</option><option v-for="s in subjects" :key="s.id" :value="s.id">{{s.name}}</option></select></div><div class="col-md-5"><label for="course-grade-filter" class="form-label">Grade level</label><select id="course-grade-filter" v-model="filters.grade_level_id" class="form-select"><option :value="null">All grades</option><option v-for="g in gradeLevels" :key="g.id" :value="g.id">{{g.name}}</option></select></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Filter</button></div></div></form>
<div v-if="!courses.length" class="empty-state card">No courses match these filters.</div><div v-else class="table-responsive card"><table class="table align-middle mb-0"><thead><tr><th>Course</th><th>Subject</th><th>Grade range</th><th>Ownership</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="course in courses" :key="course.id"><td><strong>{{course.name}}</strong><small class="d-block text-secondary">{{course.code}}</small></td><td>{{course.subject.name}}</td><td>{{course.minimum_grade_level?.name??'All'}}<span v-if="course.maximum_grade_level&&course.maximum_grade_level_id!==course.minimum_grade_level_id"> – {{course.maximum_grade_level.name}}</span></td><td><OwnershipBadge :shared="course.is_shared"/></td><td class="text-capitalize">{{course.status}}</td><td class="text-end"><Link v-if="canManage&&!course.is_shared" class="btn btn-sm btn-outline-secondary" :href="route('academic.courses.edit',course.id)">Edit</Link></td></tr></tbody></table></div>
</AuthenticatedLayout></template>
